_,d=load_panel();cv=pd.read_csv(ROOT/'experiments/E02_confounding/harmonized_landcover_climate_covariates.csv');d=d.merge(cv,on='grid_id',validate='many_to_one');fields=['LC2018_grid_mode','climate_annual_temp_C','climate_annual_precip_mm','elevation'];d=d.dropna(subset=fields);grid=d.drop_duplicates('grid_id').copy();cut={}
for col in fields[1:]:
 _,bins=pd.qcut(grid[col],3,retbins=True,duplicates='drop');bins[0]=-np.inf;bins[-1]=np.inf;cut[col]=bins.tolist();d[col+'_bin']=pd.cut(d[col],bins,labels=False)
