counts=s.groupby('stratum').grid_id.nunique().reindex(strata).to_numpy();w=counts/counts.sum();grids=pd.Index(s.grid_id.unique());gi=grids.get_indexer(s.grid_id);ix=strata.get_indexer(s.stratum)*4+s.combo.to_numpy();G=len(grids);rng=np.random.default_rng(SEED);bootw=np.array([np.bincount(rng.integers(G,size=G),minlength=G) for _ in range(300)],dtype=float);rows=[]
